<script setup>import{ref,onMounted}from'vue';import{api}from'../services/api.js';import UiState from'../components/UiState.vue';const rows=ref([]),loading=ref(true),error=ref('');onMounted(async()=>{try{rows.value=await api.get('/audit')}catch(e){error.value=e.message}finally{loading.value=false}})</script>
<template><UiState :loading="loading" :error="error" :empty="!rows.length" empty-text="Encara no s’ha registrat cap activitat."><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuari</th><th>Acció</th><th>Entitat</th><th>Registre</th><th>IP</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td data-label="Data">{{new Date(r.created_at).toLocaleString('ca-ES')}}</td><td data-label="Usuari">{{r.user_name||'Sistema'}}</td><td data-label="Acció"><span class="badge neutral">{{r.action}}</span></td><td data-label="Entitat">{{r.entity}}</td><td data-label="Registre">{{r.record_id||'—'}}</td><td data-label="IP">{{r.ip_address||'—'}}</td></tr></tbody></table></div></UiState></template>
